"""Does a Krateo CR's `Ready` condition FLAP?  READ-ONLY: it only ever runs `kubectl get --watch`.

THE QUESTION. oasgen-provider 0.99.0 (#949) makes rest-dynamic-controller set a RecheckAfter
hint after a successful create, so the resource is re-observed in ~15s instead of a full
resync. On an eventually-consistent vendor the re-observe can return not-found and then
found, so `Ready` could go True -> False -> True. If it does the hint is harmful, not just
chatty. composition-dynamic-controller's rollup maps the CHILD's Ready *reason* and never
reads Synced, so a flapping child should make the PARENT Composition flap too -- hence two
resources observed in ONE run, in the same window.

THE DESIGN CONSTRAINT. This consumes a WATCH STREAM and never polls. A poll every N ms
cannot see a transition that completes between two polls, and would report "no flap"
having merely missed it -- a false negative indistinguishable from a true one. Every
object the apiserver emits is read, and each is stamped with the elapsed time and the
wall clock it was read at; the condition's own `lastTransitionTime` is printed beside it
because the apiserver's view of when it changed is better evidence than when this process
read it.

THE ASYMMETRY THAT DECIDES THE VERDICT. A flap that WAS observed is positive evidence and
stays a flap even if the watch dies afterwards. "No flap" is a claim about the whole
window, so it needs the whole window observed. Hence:

    FLAP     Ready.status changed more than once (any True->False->True, False->True->False
             ...). The initial observed state is not a change.            exit 1
    NO FLAP  the watch stayed up for the FULL window, >=2 objects were seen, a Ready
             condition existed, and Ready.status changed at most once.    exit 0
    VOID     it could not observe: watch failed to start, died before the window ended,
             resource never appeared, <2 events, no Ready condition ever, an ERROR event,
             the object was deleted or replaced (uid changed).            exit 2
    USAGE    the command line itself was wrong (mistyped or missing argument).
             Nothing was measured, so it is NOT a VOID: VOID is a statement about a
             run that happened.                                           exit 64

Exit 2 means VOID and only VOID. argparse hardcodes 2 for its own usage errors, so left
alone a typo would read as "the instrument correctly reported it could not measure"; the
parser used here (UsageExitParser) exits 64 (EX_USAGE, sysexits.h) instead. `--help` is
not an error and still exits 0.

With two targets the run exits 1 if EITHER flapped, else 2 if EITHER was VOID, else 0. One
half failing VOIDs only its own half and is printed as such; it is never dropped.

SELF-TEST (`--self-test`, also `--selftest`) runs offline against synthetic streams, runs
the real subprocess path against fake `kubectl` scripts, and includes a MUTATION arm: a
verdict that ignores the second transition must read the True->False->True stream as
NO FLAP, proving the flap detection is what produces FLAP. No cluster is touched.
"""
import argparse
import codecs
import dataclasses
import datetime
import json
import os
import select
import subprocess
import sys
import tempfile
import threading
import time

READY = "Ready"
DEFAULT_KUBECONFIG = "local/kubeconfig.ironic-kog"
DEFAULT_CONTEXT = "kind-ironic-kog"
EXIT_NOFLAP, EXIT_FLAP, EXIT_VOID = 0, 1, 2
# EX_USAGE from sysexits.h. argparse hardcodes exit status 2 for usage errors, which is
# the VOID code above; a distinct code keeps "I could not measure" apart from "I was
# invoked wrongly". Never reuse 2 here.
EXIT_USAGE = 64


class UsageExitParser(argparse.ArgumentParser):
    """argparse, except every usage error exits EXIT_USAGE instead of 2.

    argparse routes ALL of its usage failures (unknown argument, missing value, bad type,
    and our own `ap.error(...)` calls) through error(), which hardcodes exit status 2.
    `--help` goes through exit(0) and is deliberately left alone.
    """

    def error(self, message):
        self.print_usage(sys.stderr)
        self.exit(EXIT_USAGE, "%s: error: %s\n" % (self.prog, message))


# ---------------------------------------------------------------- stream parsing
class StreamParser:
    """Incremental parser for the concatenated, pretty-printed JSON kubectl streams.

    Chunks arrive at arbitrary byte boundaries, so a half-received object must wait for
    the rest rather than be dropped or raise.
    """

    def __init__(self):
        self.buf = ""
        self.dec = json.JSONDecoder()
        self.text = codecs.getincrementaldecoder("utf-8")(errors="replace")

    def feed_bytes(self, chunk):
        return self.feed(self.text.decode(chunk))

    def feed(self, text):
        self.buf += text
        out = []
        while True:
            s = self.buf.lstrip()
            if not s:
                self.buf = ""
                break
            try:
                obj, end = self.dec.raw_decode(s)
            except json.JSONDecodeError:
                self.buf = s          # incomplete: wait for more
                break
            out.append(obj)
            self.buf = s[end:]
        return out

    def leftover(self):
        return self.buf.strip()


def normalize(raw):
    """One decoded JSON value -> [(event kind, object)].

    Accepts the `--output-watch-events` wrapper {"type","object"}, a bare object, and a
    `kind: List` (the initial listing, in case kubectl prints it as one document).
    """
    if not isinstance(raw, dict):
        return [("ERROR", {"message": "unexpected non-object JSON in stream: %r" % (raw,)})]
    if raw.get("kind") == "List" and isinstance(raw.get("items"), list):
        return [("ADDED", it) for it in raw["items"]]
    if "type" in raw and isinstance(raw.get("object"), dict):
        return [(str(raw["type"]), raw["object"])]
    return [("OBSERVED", raw)]


@dataclasses.dataclass
class Event:
    t: float          # seconds since THIS watch started
    wall: str         # wall clock when this process read it
    kind: str         # ADDED / MODIFIED / DELETED / ERROR / OBSERVED
    obj: dict


def conditions(obj):
    c = (obj.get("status") or {}).get("conditions")
    return [x for x in c if isinstance(x, dict)] if isinstance(c, list) else []


def ready_of(obj):
    for c in conditions(obj):
        if c.get("type") == READY:
            return c
    return None


# ---------------------------------------------------------------- verdict logic
def status_changes(statuses):
    """Number of times the status differs from the previous observation."""
    return sum(1 for a, b in zip(statuses, statuses[1:]) if a != b)


@dataclasses.dataclass
class Verdict:
    label: str
    verdict: str
    changes: int
    events: int
    timeline: list
    reasons: list

    @property
    def code(self):
        return {"NO FLAP": EXIT_NOFLAP, "FLAP": EXIT_FLAP, "VOID": EXIT_VOID}[self.verdict]


def judge(label, events, covered, failure=None, changes_fn=status_changes):
    """events: [Event]; covered: the watch was still alive when the window ended;
    failure: why the watch could not run to the end, or None.

    `changes_fn` is injectable ONLY so the self-test can substitute a verdict that
    ignores the second transition (the mutation arm).
    """
    timeline, reasons = [], []
    seen = {}                 # condition type -> (status, reason, ltt)
    statuses, uids = [], []
    nchg = 0
    for ev in events:
        stamp = "+%7.2fs %s %-8s" % (ev.t, ev.wall, ev.kind)
        if ev.kind == "ERROR":
            reasons.append("watch delivered an ERROR event at +%.2fs: %s"
                           % (ev.t, (ev.obj.get("message") or ev.obj)))
            timeline.append("%s ERROR" % stamp)
            continue
        if ev.kind == "DELETED":
            reasons.append("object was DELETED at +%.2fs; the rest of the window is unobserved" % ev.t)
            timeline.append("%s (object deleted)" % stamp)
            continue
        uid = (ev.obj.get("metadata") or {}).get("uid")
        if uid is not None:
            if uids and uid != uids[-1]:
                reasons.append("uid changed at +%.2fs: a different object, not one resource's history"
                               % ev.t)
            uids.append(uid)
        conds = conditions(ev.obj)
        if not conds and not timeline:
            timeline.append("%s (no conditions yet)" % stamp)
        # Ready first so its line leads, then the rest in a stable order.
        for c in sorted(conds, key=lambda c: (c.get("type") != READY, str(c.get("type")))):
            ty = c.get("type")
            key = (c.get("status"), c.get("reason"), c.get("lastTransitionTime"))
            if seen.get(ty) == key:
                continue
            prev = seen.get(ty)
            seen[ty] = key
            note = ""
            if ty == READY:
                statuses.append(c.get("status"))
                if len(statuses) > 1 and statuses[-1] != statuses[-2]:
                    nchg += 1
                    note = "   <- Ready status change #%d" % nchg
            if prev and prev[0] == key[0] and prev[2] != key[2]:
                note += "   (ltt advanced, status unchanged)" if ty == READY else ""
            timeline.append("%s %-12s %-8s %-28s ltt=%s%s"
                            % (stamp, ty, key[0], key[1], key[2], note))

    # Re-observations that did not change Ready still count as observations of its status.
    seq = []
    for ev in events:
        if ev.kind in ("ERROR", "DELETED"):
            continue
        r = ready_of(ev.obj)
        if r is not None:
            seq.append(r.get("status"))
    changes = changes_fn(seq)

    nobs = len([e for e in events if e.kind not in ("ERROR",)])
    if failure:
        reasons.append(failure)
    if not covered and not failure:
        reasons.append("the window was not covered")
    if not events:
        reasons.append("the resource never appeared (zero events)")
    elif nobs < 2:
        reasons.append("only %d event(s); a transition needs at least 2" % nobs)
    if events and not seq:
        reasons.append("no `Ready` condition was ever observed on the resource")

    if changes > 1:
        verdict = "FLAP"      # observed oscillation stands whatever happened to the watch after
    elif reasons:
        verdict = "VOID"
    else:
        verdict = "NO FLAP"
    return Verdict(label, verdict, changes, len(events), timeline, reasons)


# ---------------------------------------------------------------- the live watch
@dataclasses.dataclass
class Target:
    label: str
    resource: str
    name: str
    namespace: str
    kubectl: str = "kubectl"
    kubeconfig: str = DEFAULT_KUBECONFIG
    context: str = DEFAULT_CONTEXT


def build_cmd(t):
    """The only command this tool ever runs: a read-only `get --watch`.

    Selecting by `--field-selector metadata.name=` rather than naming the object lets the
    watch start BEFORE the CR exists (an empty list, then the ADDED event) instead of
    failing NotFound on a CR the experimenter has not applied yet.
    """
    cmd = [t.kubectl, "--kubeconfig", t.kubeconfig, "--context", t.context,
           "get", t.resource, "--field-selector", "metadata.name=%s" % t.name]
    if t.namespace:
        cmd += ["-n", t.namespace]
    return cmd + ["--watch", "--output-watch-events", "-o", "json"]


def _now_wall():
    return datetime.datetime.now(datetime.timezone.utc).strftime("%H:%M:%S.%f")[:-3] + "Z"


def run_watch(cmd, window):
    """-> (events, covered, failure). Never raises: every failure is a VOID reason."""
    events, parser = [], StreamParser()
    try:
        errf = tempfile.TemporaryFile()
        p = subprocess.Popen(cmd, stdout=subprocess.PIPE, stderr=errf, stdin=subprocess.DEVNULL)
    except OSError as e:
        return events, False, "cannot start %s: %s" % (cmd[0], e)

    t0 = time.monotonic()
    deadline = t0 + window
    covered, failure = False, None
    fd = p.stdout.fileno()
    try:
        while True:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                covered = True
                break
            ready, _, _ = select.select([fd], [], [], min(remaining, 0.25))
            if not ready:
                continue
            chunk = os.read(fd, 65536)
            if not chunk:
                rc = p.wait()
                errf.seek(0)
                tail = errf.read().decode("utf-8", "replace").strip().splitlines()[-3:]
                failure = ("watch ended at +%.1fs with exit %s, before the %ss window was covered%s"
                           % (time.monotonic() - t0, rc, window,
                              (": " + " | ".join(tail)) if tail else ""))
                break
            el, wall = time.monotonic() - t0, _now_wall()
            for raw in parser.feed_bytes(chunk):
                for kind, obj in normalize(raw):
                    events.append(Event(el, wall, kind, obj))
    except Exception as e:                      # a bug here must VOID this half, not the run
        failure = "watcher error: %s: %s" % (type(e).__name__, e)
    finally:
        if p.poll() is None:
            p.terminate()
            try:
                p.wait(timeout=5)
            except subprocess.TimeoutExpired:
                p.kill()
                p.wait()
        errf.close()
    return events, covered and failure is None, failure


def observe_all(targets, window, changes_fn=status_changes):
    """One thread per target; each result is independent, so one failing half VOIDs only itself."""
    results = {}

    def work(t):
        try:
            ev, covered, failure = run_watch(build_cmd(t), window)
            results[t.label] = judge(t.label, ev, covered, failure, changes_fn)
        except Exception as e:
            results[t.label] = Verdict(t.label, "VOID", 0, 0, [],
                                       ["internal error: %s: %s" % (type(e).__name__, e)])

    threads = [threading.Thread(target=work, args=(t,), daemon=True) for t in targets]
    for th in threads:
        th.start()
    for th in threads:
        th.join()
    return [results[t.label] for t in targets]


def overall(verdicts):
    if any(v.verdict == "FLAP" for v in verdicts):
        return EXIT_FLAP
    if any(v.verdict == "VOID" for v in verdicts):
        return EXIT_VOID
    return EXIT_NOFLAP


def render(v, target=None, window=None):
    out = ["== %s%s ==" % (v.label, ("  %s/%s" % (target.resource, target.name)) if target else "")]
    out += ["  " + l for l in v.timeline] or ["  (no timeline)"]
    out.append("  VERDICT %s: Ready status changes=%d, events=%d%s"
               % (v.verdict, v.changes, v.events,
                  (", window=%ss" % window) if window else ""))
    out += ["    reason: " + r for r in v.reasons]
    return "\n".join(out)


# ---------------------------------------------------------------- self-test
def _cond(status, reason="Reason", n=0, ty=READY):
    return {"type": ty, "status": status, "reason": reason,
            "lastTransitionTime": "2026-11-28T10:00:%02dZ" % n}


def _obj(conds, rv=1, uid="u1"):
    return {"apiVersion": "x/v1", "kind": "K",
            "metadata": {"name": "n", "uid": uid, "resourceVersion": str(rv)},
            "status": {"conditions": conds}}


def _events(objs, kind="MODIFIED", dt=1.0):
    return [Event(i * dt, "10:00:%02d.000Z" % i, "ADDED" if i == 0 else kind, o)
            for i, o in enumerate(objs)]


def _seq(statuses):
    return [_obj([_cond(s, "R%d" % i, i)], rv=i) for i, s in enumerate(statuses)]


def _fake(tmp, name, objs, stay, log):
    p = os.path.join(tmp, name)
    with open(p, "w") as f:
        f.write("#!%s\nimport sys, time, json\n"
                "open(%r, 'w').write(json.dumps(sys.argv[1:]))\n"
                "for o in json.loads(%r):\n"
                "    print(json.dumps({'type': 'MODIFIED', 'object': o}, indent=2)); sys.stdout.flush()\n"
                "    time.sleep(0.05)\n"
                "%s\n" % (sys.executable, log, json.dumps(objs),
                          "time.sleep(60)" if stay else "sys.exit(7)"))
    os.chmod(p, 0o755)
    return p


def self_test():
    passed = total = 0

    def check(label, ok):
        nonlocal passed, total
        total += 1
        passed += 1 if ok else 0
        print("  %s %s" % ("ok  " if ok else "FAIL", label))

    print("SELF-TEST")

    def verdict(statuses, covered=True, failure=None, fn=status_changes):
        return judge("t", _events(_seq(statuses)), covered, failure, fn)

    # -- the verdict function can return each outcome
    v = verdict(["False", "True"])
    check("monotonic False->True is NO FLAP (1 change)", (v.verdict, v.changes) == ("NO FLAP", 1))
    v = verdict(["True", "False", "True"])
    check("True->False->True is FLAP (2 changes)", (v.verdict, v.changes) == ("FLAP", 2))
    v = verdict(["False", "True", "False", "True"])
    check("False->True->False->True is FLAP with 3 changes", (v.verdict, v.changes) == ("FLAP", 3))
    check("a FLAP timeline marks each status change", sum("Ready status change #" in l for l in v.timeline) == 3)
    v = verdict(["True", "True", "True"])
    check("a stable Ready is NO FLAP with 0 changes", (v.verdict, v.changes) == ("NO FLAP", 0))
    v = verdict(["True"])
    check("one event only is VOID", v.verdict == "VOID" and any("only 1" in r for r in v.reasons))
    v = judge("t", [], True)
    check("zero events is VOID (never appeared)", v.verdict == "VOID" and any("never appeared" in r for r in v.reasons))
    v = verdict(["False", "True"], covered=False, failure="watch ended at +3.0s")
    check("a stream that ends before the window is VOID, not NO FLAP", v.verdict == "VOID")
    v = verdict(["False", "True"], covered=False)
    check("an uncovered window with no stated failure is still VOID", v.verdict == "VOID")
    noready = [_obj([_cond("True", ty="Synced")], rv=i) for i in range(3)]
    v = judge("t", _events(noready), True)
    check("conditions that never include Ready is VOID", v.verdict == "VOID" and any("Ready" in r for r in v.reasons))
    v = judge("t", _events([_obj([]) for _ in range(3)]), True)
    check("an object with no conditions at all is VOID", v.verdict == "VOID")
    v = verdict(["True", "False", "True"], covered=False, failure="watch died")
    check("an observed flap stays FLAP even if the watch died afterwards", v.verdict == "FLAP")
    ev = _events(_seq(["False", "True"])) + [Event(5.0, "10:00:05.000Z", "DELETED", _seq(["True"])[0])]
    check("a DELETED event makes a clean stream VOID", judge("t", ev, True).verdict == "VOID")
    ev = _events(_seq(["False", "True"])) + [Event(5.0, "10:00:05.000Z", "ERROR", {"message": "too old"})]
    check("an ERROR event makes a clean stream VOID", judge("t", ev, True).verdict == "VOID")
    objs = _seq(["False", "True"])
    objs[1]["metadata"]["uid"] = "other"
    check("a changed uid is VOID", judge("t", _events(objs), True).verdict == "VOID")
    two = [_obj([_cond("True", "A", 1), _cond("False", "B", 2, ty="Synced")], 1),
           _obj([_cond("True", "A", 1), _cond("True", "B", 3, ty="Synced")], 2)]
    v = judge("t", _events(two), True)
    check("non-Ready condition changes are shown but never counted as a flap",
          v.verdict == "NO FLAP" and v.changes == 0 and any("Synced" in l for l in v.timeline))
    same = [_obj([_cond("True", "A", 1)], 1), _obj([_cond("True", "A", 9)], 2)]
    v = judge("t", _events(same), True)
    check("ltt advancing with status unchanged is annotated, not counted",
          v.verdict == "NO FLAP" and any("ltt advanced" in l for l in v.timeline))

    # -- MUTATION ARM: ignore the second transition
    ignore_second = lambda seq: min(status_changes(seq), 1)
    real = verdict(["True", "False", "True"])
    mut = verdict(["True", "False", "True"], fn=ignore_second)
    check("MUTATION: ignoring the 2nd transition turns True->False->True into NO FLAP "
          "(real=%s, mutant=%s)" % (real.verdict, mut.verdict),
          real.verdict == "FLAP" and mut.verdict == "NO FLAP")
    mut3 = verdict(["False", "True", "False", "True"], fn=ignore_second)
    check("MUTATION: same on the 3-change stream", mut3.verdict == "NO FLAP")
    check("MUTATION control: the mutant still passes the monotonic case",
          verdict(["False", "True"], fn=ignore_second).verdict == "NO FLAP")

    # -- stream parsing
    blob = "".join(json.dumps({"type": "MODIFIED", "object": o}, indent=2) + "\n" for o in _seq(["False", "True"]))
    got = []
    sp = StreamParser()
    for i in range(0, len(blob), 7):
        got += sp.feed_bytes(blob[i:i + 7].encode())
    check("parser reassembles objects split at arbitrary 7-byte boundaries", len(got) == 2 and not sp.leftover())
    sp = StreamParser()
    first_end = blob.index("\n}\n") + 3
    half = sp.feed(blob[:first_end + 20])
    check("parser holds a half-received second object instead of dropping it",
          len(half) == 1 and bool(sp.leftover()) and len(sp.feed(blob[first_end + 20:])) == 1)
    enc = json.dumps({"k": "caf\u00e9"}, ensure_ascii=False).encode()
    cut = enc.index(b"\xc3") + 1
    sp = StreamParser()
    raw = sp.feed_bytes(enc[:cut]) + sp.feed_bytes(enc[cut:])
    check("parser tolerates a multibyte char split across chunks", raw == [{"k": "caf\u00e9"}])
    check("normalize: wrapped event", normalize({"type": "ADDED", "object": {"a": 1}}) == [("ADDED", {"a": 1})])
    check("normalize: bare object", normalize({"kind": "K", "metadata": {}})[0][0] == "OBSERVED")
    check("normalize: List expands to ADDED per item",
          normalize({"kind": "List", "items": [{"a": 1}, {"b": 2}]}) == [("ADDED", {"a": 1}), ("ADDED", {"b": 2})])
    check("normalize: a non-object becomes an ERROR event", normalize([1])[0][0] == "ERROR")

    # -- the command is read-only and carries the isolated kubeconfig/context
    t = Target("child", "r.g", "nm", "ns")
    cmd = build_cmd(t)
    check("command pins --kubeconfig local/kubeconfig.ironic-kog and --context kind-ironic-kog",
          cmd[1:5] == ["--kubeconfig", DEFAULT_KUBECONFIG, "--context", DEFAULT_CONTEXT])
    check("the only verb is `get`, and it is a watch", cmd[5] == "get" and "--watch" in cmd)
    check("no mutating verb appears anywhere in the command",
          not {"create", "apply", "patch", "delete", "replace", "edit", "scale", "annotate", "label"} & set(cmd))

    # -- the REAL subprocess path against fake kubectl scripts, five halves in parallel
    with tempfile.TemporaryDirectory() as tmp:
        logs = {n: os.path.join(tmp, n + ".argv") for n in ("mono", "flap", "early", "silent")}
        fakes = {
            "mono": _fake(tmp, "mono", _seq(["False", "True"]), True, logs["mono"]),
            "flap": _fake(tmp, "flap", _seq(["True", "False", "True"]), True, logs["flap"]),
            "early": _fake(tmp, "early", _seq(["False", "True"]), False, logs["early"]),
            "silent": _fake(tmp, "silent", [], True, logs["silent"]),
        }
        targets = [Target(n, "r.g", "nm", "ns", kubectl=p) for n, p in fakes.items()]
        targets.append(Target("missing", "r.g", "nm", "ns", kubectl=os.path.join(tmp, "no-such-kubectl")))
        res = {v.label: v for v in observe_all(targets, 1.5)}
        check("live: a monotone stream over the full window is NO FLAP", res["mono"].verdict == "NO FLAP")
        check("live: a True->False->True stream is FLAP", res["flap"].verdict == "FLAP" and res["flap"].changes == 2)
        check("live: a watch that exits before the window is VOID",
              res["early"].verdict == "VOID" and any("ended" in r for r in res["early"].reasons))
        check("live: a watch that never emits is VOID (never appeared)",
              res["silent"].verdict == "VOID" and any("never appeared" in r for r in res["silent"].reasons))
        check("live: a kubectl that cannot start VOIDs only its own half",
              res["missing"].verdict == "VOID" and res["mono"].verdict == "NO FLAP")
        argv = json.load(open(logs["mono"]))
        check("live: the fake kubectl was actually invoked with the pinned kubeconfig and context",
              argv[:4] == ["--kubeconfig", DEFAULT_KUBECONFIG, "--context", DEFAULT_CONTEXT] and argv[4] == "get")
        check("overall: FLAP outranks VOID outranks NO FLAP in the exit code",
              overall([res["flap"], res["missing"]]) == EXIT_FLAP
              and overall([res["mono"], res["missing"]]) == EXIT_VOID
              and overall([res["mono"]]) == EXIT_NOFLAP)

    # -- exit codes: usage errors must NOT be 2 (VOID). Real subprocesses, so the status
    # -- checked is the one a shell sees, not what main() happens to return.
    def run_cli(*args):
        r = subprocess.run([sys.executable, "-I", os.path.abspath(__file__)] + list(args),
                           stdin=subprocess.DEVNULL, capture_output=True, text=True, timeout=60)
        return r.returncode, r.stdout + r.stderr

    check("exit codes: the three verdict codes are 0/1/2 and usage is 64, all distinct",
          (EXIT_NOFLAP, EXIT_FLAP, EXIT_VOID, EXIT_USAGE) == (0, 1, 2, 64))
    check("the CLI parser is the UsageExitParser subclass, not bare argparse",
          type(build_parser()) is UsageExitParser and type(build_parser()) is not argparse.ArgumentParser)
    rc, out = run_cli("--no-such-flag")
    check("CLI: an unknown/mistyped argument exits 64, NOT 2 (got %d)" % rc,
          rc == EXIT_USAGE and "unrecognized arguments" in out)
    rc, out = run_cli("--window")
    check("CLI: an option missing its value exits 64, NOT 2 (got %d)" % rc,
          rc == EXIT_USAGE and "expected one argument" in out)
    rc, out = run_cli()
    check("CLI: a missing required target (no --child/--parent) exits 64, NOT 2 (got %d)" % rc,
          rc == EXIT_USAGE and "give --child and/or --parent" in out)
    rc, out = run_cli("--child", "no-slash")
    check("CLI: a malformed RESOURCE/NAME (our own ap.error) exits 64, NOT 2 (got %d)" % rc,
          rc == EXIT_USAGE and "RESOURCE/NAME" in out)
    rc, out = run_cli("--help")
    check("CLI: --help exits 0 and documents the 64 code (got %d)" % rc, rc == 0 and "64 usage error" in out)
    with tempfile.TemporaryDirectory() as tmp:
        rc, out = run_cli("--parent", "r.g/nm", "--kubectl", os.path.join(tmp, "no-such-kubectl"),
                          "--window", "1")
    check("CLI: a run that could not observe still exits 2 (VOID), pinned against 64 (got %d)" % rc,
          rc == EXIT_VOID and "VERDICT VOID" in out)

    print("SELF-TEST: %d/%d assertions passed" % (passed, total))
    return 0 if passed == total else 1


# ---------------------------------------------------------------- CLI
def build_parser():
    ap = UsageExitParser(
        allow_abbrev=False,
        description="Report whether a Krateo CR's Ready condition flaps. Read-only: only `kubectl get --watch`.",
        epilog="Exit: 0 NO FLAP, 1 FLAP, 2 VOID (any half), 64 usage error. "
               "No PyYAML is used, so there is no exit 3.")
    ap.add_argument("--self-test", "--selftest", action="store_true", dest="self_test",
                    help="run the offline self-test and exit")
    ap.add_argument("--child", metavar="RESOURCE/NAME",
                    help="e.g. baremetalnodes.baremetal.ogen.krateo.io/NAME")
    ap.add_argument("--parent", metavar="RESOURCE/NAME",
                    help="e.g. baremetalhosts.composition.krateo.io/NAME")
    ap.add_argument("-n", "--namespace", default="default", help="namespace of both (default: default)")
    ap.add_argument("--window", type=float, default=600.0,
                    help="seconds the watch must stay up (default 600; the resync is 180s, so a window "
                         "shorter than a few resyncs cannot support a NO FLAP)")
    ap.add_argument("--kubeconfig", default=DEFAULT_KUBECONFIG)
    ap.add_argument("--context", default=DEFAULT_CONTEXT)
    ap.add_argument("--kubectl", default="kubectl")
    return ap


def main(argv=None):
    ap = build_parser()
    a = ap.parse_args(argv)

    if a.self_test:
        return self_test()
    targets = []
    for label, spec in (("child", a.child), ("parent", a.parent)):
        if spec:
            if "/" not in spec:
                ap.error("--%s must be RESOURCE/NAME, got %r" % (label, spec))
            res, name = spec.rsplit("/", 1)
            targets.append(Target(label, res, name, a.namespace, a.kubectl, a.kubeconfig, a.context))
    if not targets:
        ap.error("give --child and/or --parent (or --self-test)")
    if a.window <= 0:
        ap.error("--window must be positive")

    print("watching %d resource(s) for %ss, kubeconfig=%s context=%s"
          % (len(targets), a.window, a.kubeconfig, a.context), flush=True)
    verdicts = observe_all(targets, a.window)
    for v, t in zip(verdicts, targets):
        print(render(v, t, a.window))
    print("OVERALL: " + "  ".join("%s=%s(%d changes)" % (v.label, v.verdict, v.changes) for v in verdicts))
    return overall(verdicts)


if __name__ == "__main__":
    sys.exit(main())
